import unittest
from kvparser import parse_kv

class TestParseKV(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(parse_kv("retries=3"), ("retries", "3"))

    def test_value_contains_equals(self):
        self.assertEqual(parse_kv("url=https://x.example/?a=1"), ("url", "https://x.example/?a=1"))

if __name__ == "__main__":
    unittest.main()
